-- ============================================================
-- MODULE: IT Third-Party Risk Assessment — การประเมินความเสี่ยงของบุคคลภายนอก (3rd Party Risk Assessment)
-- DESCRIPTION: 1 การประเมิน = บุคคล/องค์กรภายนอก 1 ราย ต่อ 1 ครั้งที่ประชุมประเมิน (ประเมินซ้ำได้ ยกค่าจากครั้งก่อนมาได้)
--              ข้อประเมินตามแบบฟอร์ม 10 หมวด (Risk Cluster) × 8 ข้อ ตาม พ.ร.บ.ไซเบอร์ — สร้างจากแม่แบบ it_tp_template
--              แต่ละข้อ: ภัยคุกคาม ช่องโหว่ กระทบ C/I/A ความรุนแรงแต่ละด้าน B/F S R I L O โอกาสเกิด × ความรุนแรง
--              การตอบสนอง แผนจัดการ (คำแนะนำให้แก่ผู้ให้บริการ) ผู้รับผิดชอบ ความคืบหน้า กำหนดเสร็จ
--              ความเสี่ยงคงเหลือ (C/I/A ด้าน โอกาส × ความรุนแรง) และการดำเนินการเพิ่มเติม
-- ระดับ: ก่อนจัดการ 12.5 วิกฤติ · 9.5 สูง · 3.5 ปานกลาง · ต่ำ
--        หลังจัดการ 12.5 วิกฤติ · 9.5 สูง · 5.01 ปานกลาง · ไม่เกิน 5.0 ต่ำ (คำนวณที่หน้าเว็บ)
-- PAGE: /information-technology/third-party-risk
-- DATABASE: PostgreSQL / SCHEMA: core_kon · รันซ้ำได้ · ต้องรันหลัง it_bia.sql
-- ============================================================

-- หมวดความเสี่ยง (Risk Cluster) ของแม่แบบ
CREATE TABLE IF NOT EXISTS core_kon.it_tp_clusters (
    cluster_no  SMALLINT PRIMARY KEY,
    name        VARCHAR(255) NOT NULL
);

-- ข้อประเมินของแม่แบบ — การประเมินใหม่คัดลอกจากที่นี่ (แก้แม่แบบไม่กระทบการประเมินที่ทำไปแล้ว)
CREATE TABLE IF NOT EXISTS core_kon.it_tp_template (
    item_no         VARCHAR(10) PRIMARY KEY,                -- 1.1 … 10.8
    cluster_no      SMALLINT NOT NULL REFERENCES core_kon.it_tp_clusters(cluster_no),
    sort            INTEGER NOT NULL,
    risk            TEXT NOT NULL,                          -- ข้อความความเสี่ยง เช่น "ไม่มีการแต่งตั้ง CISO / DPO ..."
    threat          TEXT,
    vulnerability   TEXT,
    treatment_plan  TEXT,                                   -- คำแนะนำให้แก่ผู้ให้บริการ (คั่นแต่ละข้อด้วย " | ")
    is_active       BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS core_kon.it_tp_assessments (
    id               SERIAL PRIMARY KEY,
    vendor_name      VARCHAR(255) NOT NULL,                 -- ชื่อบุคคล/องค์กรภายนอก
    service_name     VARCHAR(255),                          -- ระบบบริการที่สำคัญ
    bia_service_id   INTEGER REFERENCES core_kon.it_bia_services(id),
    reviewer         VARCHAR(255),                          -- ผู้พิจารณาประเมิน
    recorder_id      INTEGER REFERENCES core_kon.users(id), -- ผู้บันทึก = บัญชีเจ้าหน้าที่ IT
    recorder_name    VARCHAR(150),                          -- ชื่อผู้บันทึก ณ วันบันทึก
    recorder_role    VARCHAR(150),
    meeting_date     DATE,                                  -- วันที่ทำการประชุมความเสี่ยงพร้อมบันทึก
    notes            TEXT,
    created_by       INTEGER REFERENCES core_kon.users(id),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by       INTEGER REFERENCES core_kon.users(id),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_it_tp_assessments_vendor ON core_kon.it_tp_assessments (lower(vendor_name), meeting_date DESC);

CREATE TABLE IF NOT EXISTS core_kon.it_tp_items (
    id                   SERIAL PRIMARY KEY,
    assessment_id        INTEGER NOT NULL REFERENCES core_kon.it_tp_assessments(id),
    cluster_no           SMALLINT NOT NULL,
    cluster_name         VARCHAR(255) NOT NULL,
    item_no              VARCHAR(10) NOT NULL,
    sort                 INTEGER NOT NULL,
    risk                 TEXT NOT NULL,
    threat               TEXT,
    vulnerability        TEXT,
    cia                  TEXT[] NOT NULL DEFAULT '{}',          -- C I A
    impact_areas         TEXT[] NOT NULL DEFAULT '{}',          -- F(B/F) S R I L O
    likelihood           SMALLINT CHECK (likelihood BETWEEN 1 AND 5),   -- ว่าง = ยังไม่ประเมิน
    impact               SMALLINT CHECK (impact BETWEEN 1 AND 5),
    score                SMALLINT GENERATED ALWAYS AS (likelihood * impact) STORED,
    treatment            VARCHAR(20) NOT NULL DEFAULT 'mitigate' CHECK (treatment IN ('mitigate', 'accept', 'transfer', 'avoid', 'monitor')),
    treatment_plan       TEXT,
    owner                VARCHAR(255),
    progress_pct         SMALLINT NOT NULL DEFAULT 0 CHECK (progress_pct BETWEEN 0 AND 100),
    due_date             DATE,
    residual_cia         TEXT[] NOT NULL DEFAULT '{}',
    residual_areas       TEXT[] NOT NULL DEFAULT '{}',
    residual_likelihood  SMALLINT CHECK (residual_likelihood BETWEEN 1 AND 5),
    residual_impact      SMALLINT CHECK (residual_impact BETWEEN 1 AND 5),
    residual_score       SMALLINT GENERATED ALWAYS AS (residual_likelihood * residual_impact) STORED,
    further_action       TEXT,                                  -- ดำเนินการเพิ่มเติมเพื่อลดความเสี่ยงให้น้อยลงอีก
    copied_from          INTEGER REFERENCES core_kon.it_tp_items(id),
    created_by           INTEGER REFERENCES core_kon.users(id),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by           INTEGER REFERENCES core_kon.users(id),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT it_tp_items_pair CHECK ((likelihood IS NULL) = (impact IS NULL)),
    CONSTRAINT it_tp_items_residual_pair CHECK ((residual_likelihood IS NULL) = (residual_impact IS NULL)),
    CONSTRAINT it_tp_items_no UNIQUE (assessment_id, item_no)
);
CREATE INDEX IF NOT EXISTS idx_it_tp_items_assessment ON core_kon.it_tp_items (assessment_id, sort, id);

-- ทุกการสร้าง/แก้/ลบ เก็บค่าก่อน-หลัง (log ไม่ผูก FK กับรายการ เพื่อให้ประวัติยังอยู่หลังลบ)
CREATE TABLE IF NOT EXISTS core_kon.it_tp_log (
    id             SERIAL PRIMARY KEY,
    assessment_id  INTEGER NOT NULL REFERENCES core_kon.it_tp_assessments(id),
    item_id        INTEGER,
    action         VARCHAR(20) NOT NULL CHECK (action IN ('create_assessment', 'update_assessment', 'create', 'update', 'delete', 'copy')),
    before         JSONB,
    after          JSONB,
    changed_by     INTEGER REFERENCES core_kon.users(id),
    changed_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_it_tp_log ON core_kon.it_tp_log (assessment_id, changed_at DESC);

COMMENT ON TABLE core_kon.it_tp_assessments IS 'การประเมินความเสี่ยงของบุคคลภายนอก (3rd Party) — 1 แถว = 1 ราย ต่อ 1 ครั้งที่ประเมิน';
COMMENT ON TABLE core_kon.it_tp_items IS 'ข้อประเมิน 10 หมวด ตาม พ.ร.บ.ไซเบอร์ — คัดลอกจาก it_tp_template หรือจากการประเมินครั้งก่อน';

-- ── แม่แบบตามแบบฟอร์ม (เพิ่มเฉพาะที่ยังไม่มี — แก้ข้อความในฐานแล้วรันซ้ำไม่ทับ) ──
