INSERT INTO core_kon.it_tp_template (item_no, cluster_no, sort, risk, threat, vulnerability, treatment_plan) VALUES
    ('1.1', 1, 1, 'ไม่มีการแต่งตั้ง CISO / DPO หรือผู้ที่รับผิดชอบทางด้านไซเบอร์และป้องกันข้อมูลบุคคล', 'ไม่มีการแต่งตั้ง CISO / DPO อย่างเป็นทางการ', 'ขาดความรับผิดชอบที่ชัดเจนในการควบคุมความมั่นคงปลอดภัย', 'จัดทำคำสั่งแต่งตั้ง CISO / DPO ที่ชัดเจน และประกาศใช้อย่างเป็นทางการ | จัดทำ Org Chart และกำหนดหน้าที่ให้ชัดเจน'),
    ('1.2', 1, 2, 'ไม่มีนโยบายความมั่นคงปลอดภัยไซเบอร์และข้อมูลสารสนเทศ', 'ขาดนโยบายความมั่นคงปลอดภัยที่ครอบคลุม', 'นโยบายไม่ครอบคลุมทุกประเด็นหรือไม่อัปเดต', 'จัดทำและประกาศใช้นโยบายที่สอดคล้องกับ พ.ร.บ.ไซเบอร์, ISO 27001 | จัดกระบวนการทบทวนและการอนุมัตินโยบาย'),
    ('1.3', 1, 3, 'ไม่มีการทบทวนและอัปเดตนโยบาย, ขั้นตอนการปฏิบัติงานเป็นประจำ', 'ขาดการอัปเดตนโยบายตามสถานการณ์ปัจจุบัน', 'ไม่มีผู้รับผิดชอบในการทบทวนและไม่มี Log การเปลี่ยนแปลง', 'กำหนดรอบการทบทวนการป้องกัน เช่น ปีละ 1 ครั้ง หรือเมื่อเกิดเหตุการณ์ | จัดทำ Version Control และแต่งตั้งผู้ทบทวนอย่างเป็นทางการ'),
    ('1.4', 1, 4, 'ไม่มีการเก็บหลักฐานการปฏิบัติงาน ตามนโยบาย, ขั้นตอนการปฏิบัติงาน หรืออื่นๆ', 'ไม่มีหลักฐานยืนยันการปฏิบัติตามนโยบาย', 'ขาดระบบการจัดเก็บเอกสารและหลักฐานที่ปลอดภัย', 'จัดเก็บ Log, เอกสาร, หรือรายงานผลการตรวจสอบ | ใช้ระบบ DMS - Document Management System หรือเก็บข้อมูลในพื้นที่ที่มีการควบคุมสิทธิ์เข้าถึง'),
    ('1.5', 1, 5, 'ไม่มีการกำหนดบทบาทหน้าที่ของบุคคลกรที่ชัดเจนในด้านการรักษาความมั่นคงปลอดภัยไซเบอร์', 'ชัดเจนในการดำเนินงานด้านไซเบอร์', 'ไม่มีเอกสารกำกับหน้าที่ หรือเกิดความซ้ำซ้อน', 'ระบุใน JD - Job Description ของพนักงานอย่างชัดเจน | จัดทำ Job Description/Responsibility Matrix'),
    ('1.6', 1, 6, 'ไม่มีการมอบหมายผู้รับผิดชอบในการจัดการความเสี่ยงทางด้านไซเบอร์', 'ไม่มีผู้รับผิดชอบด้าน Cyber Risk', 'ความเสี่ยงไม่ได้ถูกจัดการหรือติดตามอย่างต่อเนื่อง', 'แต่งตั้ง Risk Owner สำหรับความเสี่ยงแต่ละรายการ | ประยุกต์ Risk Register มาใช้ร่วมกับ CISOและผู้เกี่ยวข้อง'),
    ('1.7', 1, 7, 'ไม่มีการประชุมติดตามงาน การแก้ไขปัญหาด้านความมั่นคงปลอดภัยไซเบอร์', 'ติดตามปัญหาและแผนงานด้านไซเบอร์', 'ขาดการสื่อสารระหว่างฝ่ายต่างๆ', 'จัดประชุมรายเดือน พร้อมรายงานสรุป Cybersecurity Issues | จัดตั้ง Cybersecurity Committee และควรมีบันทึกการประชุม'),
    ('1.8', 1, 8, 'ไม่มีการรายงานสถานะทางด้านไซเบอร์ต่อผู้บริหาร', 'สถานะความมั่นคงปลอดภัยไซเบอร์', 'ไม่มีรูปแบบรายงานที่เข้าใจง่าย สำหรับผู้บริหาร', 'จัดทำ Cybersecurity Dashboard หรือ Executive Summary | พัฒนาแบบฟอร์มรายงานรายเดือน พร้อมการสรุป Risk Level'),
    ('2.1', 2, 9, 'ไม่มีการปฏิบัติตามข้อกำหนด พ.ร.บ.ไซเบอร์', 'ฝ่าฝืน พ.ร.บ.ไซเบอร์ ทำให้องค์กรถูกลงโทษ', 'ขาดความเข้าใจในข้อกำหนดของ พ.ร.บ.ไซเบอร์', 'จัดทำแผนปฏิบัติตาม พ.ร.บ.ไซเบอร์ พร้อมมีการตรวจสอบเป็นระยะ | อบรมผู้เกี่ยวข้องเรื่องข้อกำหนดกับแนวปฏิบัติภายในให้ถูกต้อง'),
    ('2.2', 2, 10, 'ไม่มีการปฏิบัติตามข้อกำหนด พ.ร.บ.คอมพิวเตอร์', 'มีการใช้งานระบบที่อาจเข้าข่ายผิด พ.ร.บ.คอมพิวเตอร์', 'ไม่มีคู่มือแนวปฏิบัติด้านการใช้ระบบคอมพิวเตอร์อย่างปลอดภัย', 'ตรวจสอบการใช้งานระบบ IT ให้สอดคล้องกับกฎหมาย | จัดทำนโยบายการใช้ระบบคอมพิวเตอร์และสื่อสารให้แก่ผู้ใช้งานระบบ'),
    ('2.3', 2, 11, 'ไม่มีการปฏิบัติตามข้อกำหนด พ.ร.บ.คุ้มครองข้อมูล', 'ละเมิด พ.ร.บ.คุ้มครองข้อมูล ทำให้ถูกฟ้องร้อง', 'ขาดกระบวนการควบคุมข้อมูลส่วนบุคคลอย่างเป็นระบบ', 'ทำ DPIA (Data Protection Impact Assessment) และตรวจสอบ Data Flow | แต่งตั้ง DPO และจัดทำนโยบาย PDPA พร้อมกระบวนการร้องเรียน/ถอนความยินยอม'),
    ('2.4', 2, 12, 'ไม่มีการกำหนดบุคลากร (DPO) ตาม พ.ร.บ.คุ้มครองข้อมูล', 'ไม่แต่งตั้ง DPO ตามที่กฎหมายกำหนด', 'บุคลากรไม่ทราบบทบาทหน้าที่ของ DPO', 'พิจารณาและแต่งตั้ง DPO อย่างเป็นทางการ | จัดทำ TOR / JD ของ DPO พร้อมอบรมบทบาทหน้าที่'),
    ('2.5', 2, 13, 'ไม่มีการแต่งตั้งทีมตรวจสอบความสอดคล้องของกฎหมายและข้อกำหนดในองค์กร', 'ไม่มีทีมตรวจสอบด้านกฎหมาย ทำให้ละเลยข้อกำหนดใหม่ๆ', 'ไม่มีผู้รับผิดชอบติดตามกฎหมายใหม่', 'ตั้งคณะทำงาน Legal & Compliance พร้อมกำหนดบทบาท | ติดตามข่าวสารจากหน่วยงานกำกับ เช่น สกมช, สคส หรือหน่วยงานกำกับอื่นๆ ที่เกี่ยวข้อง'),
    ('2.6', 2, 14, 'ไม่มีการตรวจสอบความสอดคล้องของกฎหมายและข้อกำหนดในองค์กร', 'ไม่เคยตรวจสอบการปฏิบัติตามกฎหมาย', 'ไม่มีแบบฟอร์มหรือเกณฑ์ตรวจสอบ', 'กำหนดแผน Audit Compliance ภายในองค์กรเป็นรายปี | จัดทำ Checklist การตรวจสอบกฎหมายและบันทึกผลตรวจ'),
    ('2.7', 2, 15, 'ไม่มีการเก็บ Log ตามระยะเวลาที่กฎหมายต่างๆกำหนดไว้', 'ไม่เก็บ Log ตามระยะเวลาที่กฎหมายกำหนด เช่น 90 วัน, 1 ปี', 'ขาดการควบคุม Log หรือ Log ถูกลบก่อนเวลา', 'จัดทำนโยบายและตั้งค่าระบบ Logging ให้ตรงตาม พ.ร.บ.คอมฯ | ใช้ SIEM หรือระบบ Log Management ที่สามารถกำหนดเวลาเก็บ Log ได้'),
    ('2.8', 2, 16, 'ไม่มีการอบรมพนักงานด้านพรบ ไซเบอร์ และ พรบ ข้อมูลส่วนบุคคล หรือ พรบ อื่นๆ ที่เกี่ยวข้อง', 'พนักงานไม่เข้าใจข้อกำหนดกฎหมาย', 'ไม่มีหลักสูตรอบรมด้านกฎหมายที่เกี่ยวข้อง', 'จัดอบรมพนักงานเป็นรายปี และหลังเข้าทำงานใหม่ | จัดทำหลักสูตรอบรมภายใน เช่น Cyber Law Awareness / PDPA Awareness'),
    ('3.1', 3, 17, 'ไม่มีการประเมินความเสี่ยงในด้านต่างๆ ตาม พรบ ไซเบอร์ และ พรบ ข้อมูลส่วนบุคคล หรือตามมาตรฐานสากลที่เกี่ยวข้อง', 'ไม่มีการประเมินความเสี่ยงไซเบอร์ที่ครอบคลุม', 'ขาดเอกสาร Risk Register หรือขาดบุคลากรผู้รับผิดชอบ', 'กำหนดกระบวนการประเมินความเสี่ยงตาม พ.ร.บ.ไซเบอร์/ISO 27001 | แต่งตั้ง Risk Owner และสร้างแบบฟอร์ม Risk Assessment'),
    ('3.2', 3, 18, 'ไม่มีการประเมินผลกระทบทางธุรกิจ (BIA – Business Impact Analyst)', 'ไม่ทราบผลกระทบทางธุรกิจเมื่อระบบล่ม', 'ไม่มีข้อมูล RTO/RPO/MTPD หรือขาดการจัดลำดับตามความสำคัญ', 'จัดทำ BIA (Business Impact Analysis) ครอบคลุมทุกระบบหลัก | จัดทำรายงาน BIA และให้เชื่อมโยงกับ BCM Plan'),
    ('3.3', 3, 19, 'ไม่มีการประเมินซ้ำ เมื่อมีการเปลี่ยนแปลงระบบบางอย่างที่สำคัญ', 'ระบบมีการเปลี่ยนแปลงแล้วแต่ไม่ได้ทำการประเมินความเสี่ยงใหม่', 'ขาดการเชื่อมโยงความสัมพันธ์ระหว่าง Change Management กับ Risk', 'สร้างขั้นตอน Risk Reassessment เมื่อมี Change Request | บังคับใช้ Change Control Process ที่รวมการประเมินความเสี่ยง'),
    ('3.4', 3, 20, 'ไม่มีการกิจกรรมหรือปฏิบัติตาม TOR / SLA ที่มีการระบุข้อกำหนดความมั่นคงปลอดภัยไซเบอร์', 'TOR/SLA ไม่ครอบคลุมข้อกำหนดด้านความมั่นคงปลอดภัยไซเบอร์', 'ไม่มีการตรวจสอบ SLA กับผู้ให้บริการ', 'กำหนดหัวข้อ Cybersecurity ใน TOR/SLA ทุกฉบับ | สร้างแบบฟอร์มตรวจสอบ SLA พร้อมใช้ KPI ในการวัดผล'),
    ('3.5', 3, 21, 'ไม่มีการจัดทำแผนบริหารความเสี่ยง (Risk Management Plan)', 'ไม่มีแผนบริหารความเสี่ยงที่เป็นระบบ', 'ขาด Template และขั้นตอนดำเนินการ', 'จัดทำ Risk Management Plan และทบทวนทุกปี | ใช้กรอบ ISO 31000 / ISO 27005 ในการเขียนแผนก็ได้'),
    ('3.6', 3, 22, 'ไม่มีการระบุสินทรัพย์สารสนเทศที่สำคัญ (Asset Inventory List > Asset Register)', 'ไม่ทราบสินทรัพย์สารสนเทศที่ต้องป้องกัน', 'ข้อมูลไม่อัปเดตหรือไม่มีเจ้าของรับผิดชอบ', 'จัดทำ Asset Inventory และกำหนด Critical Asset | ใช้ระบบ CMDB - Computer Management Database หรือ Excel + Owner Mapping'),
    ('3.7', 3, 23, 'ไม่มีการประเมินช่องโหว่ด้านไซเบอร์ (Cyber Vulnerability Assessment)', 'ไม่เคยทำการประเมินช่องโหว่ทางเทคนิค', 'ขาดเครื่องมือหรือบุคลากรทางด้านเทคนิค', 'วางแผน Cyber Vulnerability Assessment รายปี (เช่น VA/PenTest) | ใช้เครื่องมือ Open-source เช่น Nessus, OpenVAS หรือจ้างผู้เชี่ยวชาญ'),
    ('3.8', 3, 24, 'ไม่มีการวิเคราะห์รวมถึงการจัดลำดับความสำคัญของความเสี่ยงไซเบอร์ที่พบ', 'จัดการความเสี่ยงโดยไม่เรียงตามลำดับความสำคัญ', 'ไม่ทราบว่าความเสี่ยงไหนต้องทำการจัดการก่อน', 'กำหนด Risk Matrix (Impact x Likelihood) เพื่อจัดระดับความเสี่ยง | จัดทำ Cyber Risk และ Risk Treatment Plan'),
    ('4.1', 4, 25, 'ไม่มีการทำแผนรับมือภัยคุกคามไซเบอร์ (Cybersecurity Incident Response Plan)', 'ไม่มีแผนรับมือภัยคุกคามไซเบอร์ทำให้การตอบสนองล่าช้า', 'ไม่มีโครงสร้างการตอบสนอง หรือไม่เคยมีการอนุมัติในการใช้', 'จัดทำ Incident Response Plan (IRP) ตามกรอบ พ.ร.บ.ไซเบอร์ / ISO 27035 | จัดทำ IRP พร้อมลงนามโดยผู้บริหารระดับสูง'),
    ('4.2', 4, 26, 'ไม่มีการทดสอบหรือจำลองสถานการณ์ภัยคุกคาม พร้อมฝึกซ้อม', 'บุคลากรไม่รู้วิธีการตอบสนองต่อภัยคุกคาม', 'ไม่มีการซ้อมแผน BCP', 'ฝึกอบรมและฝึกซ้อมแผน เป็นประจำ | วางแผนงานการทดสอบ อย่างน้อยปีละ 1 ครั้ง พร้อมรายงานผลการฝึกซ้อม'),
    ('4.3', 4, 27, 'ไม่มีการแจ้งเตือนเมื่อเกิดเหตุการณ์ภัยคุกคามทางไซเบอร์', 'ขาดระบบแจ้งเตือนแบบเรียลไทม์เมื่อเกิดเหตุ', 'การแจ้งเตือนไม่ครอบคลุมหรือล่าช้า กว่าที่กำหนด', 'ใช้ระบบ SIEM / IDS / SOC เพื่อแจ้งเตือนเหตุการณ์ | กำหนด Use Case ที่เหมาะสม'),
    ('4.4', 4, 28, 'ไม่มีการรายงานเหตุการณ์ไปยังหน่วยงานรัฐหรือหน่วยงานกำกับดูแลที่เกี่ยวข้อง', 'ไม่รายงานเหตุการณ์ตามข้อกฎหมาย ทำให้เสี่ยงโดนลงโทษ', 'ไม่มีแบบฟอร์มหรือช่องทางการส่งรายงาน', 'สร้าง Incident Notification System/Process ไปยัง สกมช หรือหน่วยงานกำกับที่ดูแล | จัดทำแบบฟอร์มพร้อมช่องทางแจ้งที่ชัดเจน และฝึกอบรมผู้เกี่ยวข้อง'),
    ('4.5', 4, 29, 'ไม่มีการจัดเก็บหลักฐานเหตุการณ์ที่ผิดปกติ', 'ไม่มีหลักฐานเพื่อสืบสวนหรือรายงานต่อผู้บริหาร/กฎหมาย', 'เก็บหลักฐานไม่ถูกต้องหรือไม่ปลอดภัย', 'กำหนดวิธีการเก็บ Log | จัดอบรมบุคลากรและใช้ระบบจัดเก็บที่มีการเข้ารหัสและ Audit ได้'),
    ('4.6', 4, 30, 'ไม่มีช่องทางการแจ้งเหตุเหตุการณ์ภัยคุกคามทางไซเบอร์ ภายในองค์กร', 'บุคลากรไม่ทราบช่องทางการแจ้งเหตุ', 'ไม่มีการประชาสัมพันธ์ภายในองค์กร', 'สร้างช่องทางแจ้งเหตุ (Email, Hotline, Portal) ที่ชัดเจน | ติดป้าย / ประกาศภายในองค์กร และระบุในคู่มือบุคลากร (Employee Handbook)'),
    ('4.7', 4, 31, 'ไม่มีการกำหนดบทบาทผู้รับผิดชอบต่อเหตุการณ์', 'ไม่มีผู้รับผิดชอบเหตุการณ์อย่างเป็นทางการ', 'ขาดการประสานงานเมื่อเกิดเหตุ', 'แต่งตั้ง Incident Manager และ Incident Handling Team | จัดทำ Incident Role & Responsibility'),
    ('4.8', 4, 32, 'ไม่มีการประเมินผลหลังเกิดเหตุการณ์ (Post-Incident Review)', 'ไม่เคยประเมินผลหลังเกิดเหตุการณ์ ทำให้ไม่เกิดการเรียนรู้', 'ไม่มีผู้รับผิดชอบในการสรุปผลหรือไม่มีแบบฟอร์ม', 'จัดทำ Post-Incident Review (PIR) พร้อมมีการประชุม | กำหนดให้ทุก Incident ที่สำคัญต้องมี PIR และ Lessons Learned'),
    ('5.1', 5, 33, 'ไม่มีระบบ Log Management และการตรวจสอบข้อมูลย้อนหลัง', 'ไม่สามารถตรวจสอบย้อนหลังเมื่อเกิดเหตุการณ์ผิดปกติ', 'ระบบไม่จัดเก็บ Log หรือระบบไม่เป็นมาตรฐาน', 'ใช้ระบบ Log Management ที่มีการทำ Audit Logs | ใช้ SIEM หรือระบบที่เก็บ Log ตามกรอบ พ.ร.บ.คอมพิวเตอร์ (≥90 วัน)'),
    ('5.2', 5, 34, 'ไม่มีการควบคุมอุปกรณ์พกพา Notebook, USB Storage หรืออื่นๆและมีการจำกัด Remote Access อย่างเหมาะสม', 'อุปกรณ์พกพาถูกใช้โดยไม่ได้รับอนุญาต', 'ไม่มีการควบคุม USB, BYOD หรือไม่มีระบบล็อกการเข้าถึง', 'ใช้นโยบาย MDM (Mobile Device Management) และ VPN ที่ปลอดภัย | บังคับใช้ Endpoint Security และ จำกัด Remote Access โดยกฎบังคับ'),
    ('5.3', 5, 35, 'ไม่มีการใช้ VPN, Firewall, IDS/IPS เป็นไปตามมาตรฐานสากล', 'การเข้าถึงเครือข่ายไม่มีการควบคุมที่เข้มแข็ง', 'ไม่มีการ Monitoring หรือไม่มี กฎ (Rule) ที่ครอบคลุมภัยคุกคาม', 'ติดตั้ง Firewall, IDS/IPS และอัปเดต Patch อย่างสม่ำเสมอ | ตรวจสอบกฎและเงื่อนไขของ Firewall / IDS และมีการทดสอบอย่างน้อยปีละ 1 ครั้ง'),
    ('5.4', 5, 36, 'ไม่มีการแยกเครือข่าย (Network Segmentation) เช่น VLAN', 'การโจมตีสามารถกระจายไปทั่วระบบโดยง่าย', 'ระบบเครือข่ายเป็น Flat Network หรือไม่มีการแบ่ง Level', 'แบ่งเครือข่ายตามความเสี่ยง เช่น VLAN สำหรับ Admin / Guest / Server | ออกแบบ Network Architecture ใหม่โดยอิง Zero Trust Model'),
    ('5.5', 5, 37, 'ไม่มีการควบคุม Password และ User Account', 'การเข้าถึงระบบโดยใช้รหัสผ่านที่อ่อนแอ', 'ไม่มีการบังคับใช้หรือล็อกการเปลี่ยนรหัสผ่านอัตโนมัติ', 'ใช้นโยบาย Password Policy เช่น Complexity, Expiry, History | ใช้ระบบบังคับการตั้งค่าพร้อม Password Manager สำหรับผู้ใช้ระดับสูง'),
    ('5.6', 5, 38, 'ไม่มีการจำกัดสิทธิ์ตามหน้าที่ของงานที่ได้รับผิดชอบ (Least Privilege)', 'ผู้ใช้งานมีสิทธิ์เกินกว่าหน้าที่ ทำให้เสี่ยงถูกใช้ในทางที่ผิด', 'ขาดการตรวจสอบสิทธิ์ของผู้ใช้ ที่ไม่อัปเดตตาม Job Role', 'ใช้หลัก Least Privilege และ Role-Based Access Control (RBAC) | มีการทบทวนสิทธิ์เป็นรายไตรมาส และระบบอนุมัติการเปลี่ยนแปลงสิทธิ์'),
    ('5.7', 5, 39, 'ไม่มีการใช้ Multi-Factor Authentication', 'การเข้าถึงระบบไม่มีการยืนยันตัวตนหลายขั้นตอน', 'ไม่มีนโยบาย MFA หรือการใช้เฉพาะกับบางระบบ', 'เปิดใช้งาน Multi-Factor Authentication (MFA) สำหรับ Admin และผู้ใช้ที่สำคัญ | บังคับใช้ MFA ทุกช่องทางที่เข้าถึงระบบสำคัญ'),
    ('5.8', 5, 40, 'ไม่มีการตั้งค่าความปลอดภัยในระบบปฏิบัติ (OS), Network, Application หรือมาตรฐานขั้นต่ำ (Security Configuration Standard Baseline)', 'ระบบไม่ได้รับการตั้งค่าความปลอดภัยขั้นพื้นฐาน', 'ไม่มีการทำให้ระบบแข็งแกร่ง หรือใช้ค่าตั้งต้น (Default) จากโรงงาน', 'จัดทำ Baseline Configuration สำหรับ OS, Network, App | ใช้ CIS Benchmark / STIG ซึ่งทั้งสอง เป็นมาตรฐานที่ใช้ในการกำหนด "มาตรฐานการตั้งค่าความปลอดภัย" (Security Configuration Baseline)'),
    ('6.1', 6, 41, 'ไม่มีการทำสำรองข้อมูล (Backup)และมีการทดสอบการกู้คืน (Restore)', 'ข้อมูลสูญหายจากเหตุระบบล่มหรือมัลแวร์', 'Backup ไม่ครอบคลุม, ไม่เข้ารหัส หรือไม่มีการทดสอบ Restore', 'จัดทำนโยบาย Backup และทดสอบการ Restore อย่างน้อยปีละ 1 ครั้ง | ใช้ 3-2-1 Backup Rule พร้อมทดสอบการกู้คืนข้อมูลเป็นประจำ'),
    ('6.2', 6, 42, 'ไม่มีการควบคุมการใช้ระบบ Cloud หรือมีมาตรฐานรับรองต่างๆ', 'ใช้บริการ Cloud ที่ไม่มีมาตรฐานหรือมีช่องโหว่', 'ไม่เคยประเมินความเสี่ยงหรือไม่มี Cloud Policy', 'เลือกผู้ให้บริการที่ได้รับการรับรอง เช่น ISO 2701, 27018, 27701, CSA STAR | จัดทำนโยบายการใช้ Cloud พร้อมแบบฟอร์มการประเมิน Provider'),
    ('6.3', 6, 43, 'ไม่มีการควบคุมการเข้าถึงศูนย์ข้อมูลทางกายภาพ', 'บุคคลภายนอกเข้าถึงศูนย์ข้อมูลโดยไม่ได้รับอนุญาต', 'ไม่มีระบบลงทะเบียน / ควบคุมสิทธิ์เข้า-ออก', 'ใช้มาตรการควบคุม เช่น Access Card, กล้องวงจรปิด, ล็อก 2 ชั้น | จัดระบบ Visitor Log, แจ้งเตือนเมื่อมีการเข้าศูนย์ข้อมูล'),
    ('6.4', 6, 44, 'ไม่มีการเข้าระหัสในการใช้งานอุปกรณ์ USB Storage', 'ข้อมูลรั่วไหลจาก USB Drive หรืออุปกรณ์ภายนอก', 'ไม่มีการควบคุมการใช้งาน USB หรือ DLP', 'เข้ารหัสข้อมูล USB, จำกัดสิทธิ์การใช้งาน USB บนอุปกรณ์ | ใช้ Endpoint Protection ที่มี USB Control และบังคับ Encryption'),
    ('6.5', 6, 45, 'ไม่มีการลบข้อมูลอย่างปลอดภัยเมื่อสิ้นสุดการใช้งาน', 'ข้อมูลยังคงอยู่ในอุปกรณ์ที่ยกเลิกใช้งานแล้ว', 'ไม่มีนโยบายการทำลายข้อมูล', 'ใช้วิธีลบข้อมูลอย่างปลอดภัย (Secure Erase, Overwrite) | จัดทำนโยบาย Data Disposal และบันทึกหลักฐานการลบทุกครั้ง'),
    ('6.6', 6, 46, 'ไม่มีการกำหนดสิทธิ์การเข้าถึงในระดับผู้ดูแลของผู้ให้บริการระบบ Cloud', 'สิทธิ์ระดับ Admin ของ Cloud ถูกใช้ในทางไม่เหมาะสม', 'ไม่มีการควบคุมหรือ Review สิทธิ์ผู้ให้บริการ', 'กำหนด Least Privilege สำหรับ Admin Cloud | ตรวจสอบสิทธิ์ระดับ Admin ทุกไตรมาสพร้อมใช้ MFA ทุกบัญชีผู้ดูแล'),
    ('6.7', 6, 47, 'ไม่มีการใช้ NDA – Non Disclosure Agreement ในองค์กรและผู้ที่เกี่ยวข้อง', 'ข้อมูลความลับรั่วไหลจากพนักงาน / ผู้รับจ้าง', 'ไม่มีแบบฟอร์มหรือไม่มีการบังคับใช้', 'จัดทำ NDA สำหรับบุคลากร, ผู้ให้บริการ และบุคคลที่เกี่ยวข้อง | บังคับลงนาม NDA ทันทีเมื่อเริ่มงาน และเก็บรักษาไว้เป็นส่วนหนึ่งของเอกสาร HR/Legal'),
    ('6.8', 6, 48, 'ไม่มีขั้นตอนการคัดเลือกผู้ให้บริการระบบ Cloud ที่ได้มาตรฐาน', 'เลือกผู้ให้บริการ Cloud โดยไม่มีมาตรฐานการประเมิน', 'ใช้ Provider โดยไม่มีการตรวจสอบ', 'กำหนดเกณฑ์คัดเลือก โดยใช้มาตรฐานสากลต่างๆ | สร้างแบบประเมินเบื้องต้น (Cloud Selection Checklist) และตรวจสอบสถานะ Compliance'),
    ('7.1', 7, 49, 'ไม่มีการทำ Security Audit / Penetration Test เป็นประจำ', 'ไม่มีการประเมินระบบความมั่นคงปลอดภัย ทำให้พบช่องโหว่ช้า', 'ไม่มีแผนทดสอบความมั่นคงปลอดภัย หรือบุคลากรไม่พร้อม', 'วางแผนทำ Security Audit / Penetration Test เป็นประจำ (ปีละ 1–2 ครั้ง) | ใช้บุคลากรภายในหรือจ้างผู้เชี่ยวชาญภายนอกที่ผ่านการรับรอง เช่น OSCP, CEH'),
    ('7.2', 7, 50, 'ไม่มีการตรวจสอบการใช้ลิขสิทธิ์ของ Software ว่าถูกต้องตามกฎหมาย', 'ใช้ Software เถื่อนหรือไม่ได้รับอนุญาต ทำให้มีความเสี่ยง', 'ขาดระบบตรวจสอบการใช้ Software License', 'ตรวจสอบลิขสิทธิ์และจัดทำทะเบียนซอฟต์แวร์ภายใน | จัดทำนโยบายการจัดซื้อและการใช้งานซอฟต์แวร์'),
    ('7.3', 7, 51, 'ไม่มีระบบที่ใช้ช่วยในการตรวจสอบและเฝ้าระวังภัยคุกคามทางไซเบอร์', 'ไม่สามารถตรวจจับภัยคุกคามแบบเรียลไทม์', 'ขาดเครื่องมือหรือการแจ้งเตือนที่ครอบคลุม เหมาะสม', 'ใช้ระบบ SIEM, IDS/IPS หรือ EDR ในการตรวจจับและแจ้งเตือน | บูรณาการระบบ SOC ภายใน หรือใช้ outsource SOC'),
    ('7.4', 7, 52, 'ไม่มีการกำหนดตัวชี้วัด (KPI) สำหรับการรักษาความมั่นคงปลอดภัยทางไซเบอร์', 'ไม่สามารถวัดผลด้านความมั่นคงปลอดภัยได้', 'ขาดตัวชี้วัดหรือตัวชี้วัดไม่สัมพันธ์กับความเสี่ยงจริง', 'กำหนด KPI ที่วัดผลได้จริง เช่น % Incident Resolved, Time to Detect | ใช้แนวทาง SMART KPI และเชื่อมโยงกับ Cyber Risk'),
    ('7.5', 7, 53, 'ไม่มีการตรวจติดตามมาตรการที่ได้นำเสนอไว้จากตัวชี้วัด (KPI)', 'ตัวชี้วัดไม่ได้นำไปใช้งานหรือติดตามผลจริง', 'ไม่มีเจ้าภาพในการติดตามหรือตัวชี้วัดถูกละเลย', 'จัดประชุมติดตาม KPI และนำผลไปปรับปรุงแผนงาน | ระบุเจ้าภาพ (KPI Owner) และจัดทำ Dashboard รายไตรมาส'),
    ('7.6', 7, 54, 'ไม่มีการส่งเสริมและพัฒนาความสามารถของทีม IT Security', 'บุคลากร IT Security ขาดทักษะ/เครื่องมือในการทำงาน', 'ขาดแผนพัฒนาระยะยาว', 'จัดแผนอบรม/สอบใบรับรอง เช่น CISA, CISSP, ISO 27001 LI | สร้าง Individual Development Plan (IDP) สำหรับแต่ละบุคคล'),
    ('7.7', 7, 55, 'ไม่มีแผนการตรวจสอบและเฝ้าระวังภัยคุกคามไซเบอร์', 'ไม่มีแผนติดตามเฝ้าระวังภัยคุกคาม ทำให้ตรวจไม่ทันเวลา', 'ตรวจสอบเฉพาะเมื่อเกิดเหตุ ไม่ได้ติดตามแบบเชิงรุก', 'วางแผน Threat Hunting, Network Monitoring, Log Review | กำหนดกิจกรรม Monitoring รายเดือน/สัปดาห์ และแจ้งผลต่อผู้บริหาร'),
    ('7.8', 7, 56, 'ไม่มีการจัดทำแผนปรับปรุงเพื่อการพัฒนาทางไซเบอร์ ประจำปี เช่น แผนการฝึกอบรมพนักงาน', 'ขาดการวางแผนพัฒนาองค์กรด้านไซเบอร์ในระยะยาว', 'ไม่มีแผนการพัฒนาองค์กร/บุคลากรในเชิงระบบ', 'จัดทำ Cybersecurity Improvement Plan รายปี เช่น Roadmap, Training Plan | เชื่อมโยงแผนกับผล KPI, Risk Assessment และแผนกลยุทธ์องค์กร'),
    ('8.1', 8, 57, 'ไม่มีการกำหนดสิทธิ์การเข้าถึงตามหน้าที่ที่ได้รับมอบหมาย', 'ผู้ใช้เข้าถึงข้อมูลหรือระบบเกินสิทธิ์ที่ได้รับ', 'ไม่มีการจำกัดสิทธิ์ หรืออนุมัติสิทธิ์', 'ใช้นโยบาย RBAC (Role-Based Access Control) ตามหน้าที่จริง | ใช้ระบบ IAM หรือ Workflow การขอสิทธิ์ที่มีการตรวจสอบก่อนอนุมัติ'),
    ('8.2', 8, 58, 'ไม่มีการระบุและตรวจสอบตัวตนผู้ใช้งาน ก่อนใช้งานระบบ', 'การเข้าระบบโดยบุคคลผู้ที่แอบอ้าง', 'ไม่มีการตรวจสอบตัวตน หรือใช้รหัสผ่านง่าย', 'มีระบบระบุตัวตน เช่น Username/Password, Certificate, Biometrics | บังคับใช้ Password Policy และใช้ Authentication หลายปัจจัย (MFA)'),
    ('8.3', 8, 59, 'ไม่มีการใช้ MFA ในระบบสำคัญและมีการบันทึกกิจกรรมการใช้งาน', 'ไม่มีบันทึกกิจกรรมเมื่อผู้ใช้เข้าถึงระบบสำคัญ', 'Log ไม่ถูกเก็บ หรือไม่สามารถระบุผู้กระทำได้', 'เปิดใช้งาน Audit Log และใช้ MFA สำหรับระบบสำคัญ | ใช้ SIEM หรือระบบเก็บ Log ที่สอดคล้องกับกฎหมาย (เช่น >90 วัน)'),
    ('8.4', 8, 60, 'ไม่มีการควบคุมบัญชีชั่วคราว/ผู้รับเหมาที่ต้องการเข้าระบบ', 'ผู้รับเหมาเข้าระบบโดยไม่มีการควบคุมและขออนุญาต', 'ไม่มีระบบแยกการควบคุมบัญชีภายนอก', 'สร้างบัญชีชั่วคราว พร้อมระยะเวลาหมดอายุอัตโนมัติ | บังคับใช้ Contractor Access Policy และใช้ VPN / MFA เฉพาะกิจ'),
    ('8.5', 8, 61, 'ไม่มีการระงับบัญชีที่ไม่ได้ใช้งานตามที่กำหนด', 'บัญชีเก่าที่ไม่ได้ใช้งาน แต่ยังคงสามารถเข้าระบบ', 'ไม่มีการทบทวนบัญชีที่ไม่ได้ใช้งาน', 'ตั้งระบบ Auto-disable หลังไม่มีการใช้งาน เช่น 30/90 วัน | ตรวจสอบบัญชีผู้ใช้รายเดือน และลบบัญชีที่ไม่ได้ใช้งาน'),
    ('8.6', 8, 62, 'ไม่มีการตรวจสอบสิทธิ์การเข้าถึงเป็นประจำ', 'ไม่เคยตรวจสอบสิทธิ์การเข้าถึง ส่งผลให้เกิดสิทธิ์ซ้ำซ้อน', 'ไม่มี Process Review Access หรือขาดเอกสารประกอบ', 'ตรวจสอบสิทธิ์อย่างน้อยทุก 6 เดือน โดยเจ้าของระบบ | จัดทำ Access Review Checklist และลายเซ็นรับรองจากเจ้าของระบบ'),
    ('8.7', 8, 63, 'ไม่มีการแยกหน้าที่ความรับผิดชอบที่ชัดเจน (Segregation of Duties)', 'ผู้ใช้งานคนเดียวสามารถดำเนินงานโดยไม่มีการตรวจสอบ', 'บทบาทงานไม่ได้มีการแยก หรือมีบุคคลเดียวถือหลายสิทธิ์', 'จัดการแยกหน้าที่ (Segregation of Duties - SoD) เช่น การอนุมัติไม่ควรอยู่ที่คนๆเดียว | ปรับ Role / Workflow ให้มีจุดตรวจสอบ (Approval Point)'),
    ('8.8', 8, 64, 'ไม่มีการควบคุมบัญชีผู้ดูแลระบบ (Admin)', 'บัญชี Admin ถูกใช้ร่วมกันหรือไม่มีการควบคุมเฉพาะ', 'ใช้ Shared Account โดยที่ไม่มีการตรวจสอบสิทธิ์', 'จัดการบัญชีผู้ดูแลแบบรายบุคคล พร้อม MFA และ Audit Logs | บังคับให้ใช้ชื่อบัญชีระบุผู้ใช้ (Non-shared Admin Account)'),
    ('9.1', 9, 65, 'ไม่มีการจัดทำแผน BCP / DRP', 'เมื่อเกิดเหตุการณ์ร้ายแรง แล้วไม่มีแผนสำรองในการดำเนินงาน', 'ไม่เคยมีแผน BCP/DRP หรือแผน BCP/DRP เก่าไม่ได้อัปเดต', 'จัดทำแผน BCP/DRP อย่างเป็นทางการ และผ่านความเห็นชอบจากผู้บริหาร | ทบทวน BCP/DRP อย่างน้อยปีละ 1 ครั้ง หรือเมื่อระบบมีการเปลี่ยนแปลง'),
    ('9.2', 9, 66, 'ไม่มีการทดสอบแผนฟื้นฟูระบบเป็นประจำ', 'แผน BCP/DRP ไม่สามารถใช้งานได้จริงเมื่อเกิดเหตุการณ์', 'ไม่เคยทดสอบแผน BCP/DRP หรือมีเฉพาะในเอกสาร', 'วางแผนการทดสอบ เช่น Simulation หรือ Full Recovery Test | ทดสอบ BCP/DRP อย่างน้อยปีละครั้ง พร้อมจัดทำรายงานผล'),
    ('9.3', 9, 67, 'ไม่มีการกำหนด RTO, RPO, MTPD', 'ไม่รู้ว่าใช้เวลานานแค่ไหนจึงจะฟื้นฟูระบบได้', 'ไม่มีเอกสารกำหนดค่าพวกนี้ หรือไม่ตรงกับระบบจริง', 'กำหนด RTO (เวลาในการกู้คืน), RPO (ข้อมูลที่ยอมให้สูญหายได้), MTPD (เวลาสูงสุดในการหยุดชะงัก) | ควรมีการประเมินร่วมกับ BIA และผู้ใช้งานระบบ เพื่อกำหนดค่าที่เหมาะสม'),
    ('9.4', 9, 68, 'ไม่มีศูนย์สำรอง (Backup Site)', 'ไม่มี Backup Site ทำให้ไม่สามารถฟื้นฟูระบบได้', 'ไม่มีแผน BCP/DRP สำรอง หรือไม่ทดสอบศูนย์สำรองเลย', 'จัดตั้งศูนย์สำรองที่เหมาะสม เช่น Cold, Warm หรือ Hot Site | ระบุ Critical System และวางแผน DR Site ที่รองรับได้ตาม SLA'),
    ('9.5', 9, 69, 'ไม่มีการกำหนดทีมรับผิดชอบแผน BCP', 'ไม่มีทีมผู้รับผิดชอบแผน BCP / DRP', 'ไม่รู้ว่าใครรับผิดชอบช่วงเกิดเหตุ', 'แต่งตั้งทีม BCP/DRP พร้อม TOR / บทบาทหน้าที่ | ระบุชื่อผู้รับผิดชอบในแผน BCP/DRP และมีรายชื่อสำรองกรณีฉุกเฉิน'),
    ('9.6', 9, 70, 'ไม่มีการจัดเก็บแผนฟื้นฟูและข้อมูล ไว้หลายๆแห่ง', 'แผน BCP/DRP สำคัญหายหรือเข้าถึงไม่ได้เมื่อจำเป็น', 'เก็บไว้ที่เดียว หรือเก็บแบบไม่เข้ารหัส', 'จัดเก็บแผน BCP/DRP ในหลายรูปแบบ (เอกสาร, ดิจิทัล) และเก็บไว้หลายที่ (Onsite / Offsite / Cloud) | ใช้ระบบ DMS - Data Management System หรือ Cloud Drive ที่ปลอดภัย พร้อมกำหนดสิทธิ์เข้าถึง'),
    ('9.7', 9, 71, 'ไม่มีการทำคู่มือต่างๆ ที่ใช้ในการฟื้นฟูระบบ', 'บุคลากรไม่รู้วิธีการกู้คืนระบบจริง', 'ไม่มีคู่มือ หรือเป็นเอกสารที่ล้าสมัย', 'จัดทำ Recovery Manual หรือ Runbook ที่ชัดเจนต่อระบบ | จัดทำเอกสารขั้นตอนกู้คืนรายระบบ พร้อม Flowchart, Contact, Credential'),
    ('9.8', 9, 72, 'ไม่มีการวิเคราะห์ผลทางธุรกิจ รวมถึงการประเมินผลกระทบต่อระบบที่สำคัญ', 'ไม่รู้ว่าระบบใดสำคัญที่สุดเมื่อเกิดเหตุ', 'ไม่มีข้อมูลผลกระทบหากระบบหยุดชะงัก', 'ทำ Business Impact Analysis (BIA) และจัดลำดับความสำคัญระบบ | ทำ BIA อย่างเป็นระบบ ร่วมกับหน่วยงานธุรกิจ และใช้ผลเพื่อจัดลำดับฟื้นฟูระบบ'),
    ('10.1', 10, 73, 'ไม่มีการประเมินความเสี่ยง Supplier อื่นๆ ที่เกี่ยวข้อง', 'Supplier ชอบก่อให้เกิดช่องโหว่/เหตุการณ์ที่กระทบต่อองค์กร', 'ไม่มีการประเมินความเสี่ยง หรือมีใช้เกณฑ์เดียวกันทุกกรณี', 'จัดทำ Third-Party Risk Assessment สำหรับผู้ให้บริการรายสำคัญ | ทำการจัดระดับความเสี่ยงของ Supplier และประเมินตามประเภทบริการที่เกี่ยวข้อง'),
    ('10.2', 10, 74, 'ไม่มีการกำหนดข้อกำหนดด้านความมั่นคงปลอดภัยไซเบอร์', 'ไม่มีข้อกำหนดด้าน Cybersecurity กับ Supplier', 'TOR/สัญญาไม่มีข้อกำหนดด้านการป้องกันข้อมูล', 'เพิ่ม Cybersecurity Requirements ลงใน TOR, RFP (Request for Proposal), และสัญญา | ใช้ Cyber Clause Template ที่มีขั้นต่ำตาม ISO 27036 เป็นมาตรฐานเฉพาะด้านที่เกี่ยวข้องกับ การจัดการความมั่นคงปลอดภัยของข้อมูลในความสัมพันธ์กับผู้ให้บริการภายนอก (Third-Party / Supplier Security)'),
    ('10.3', 10, 75, 'ไม่มีข้อตกลงระดับการให้บริการ (SLA)', 'ไม่มี SLA ส่งผลต่อความไม่ชัดเจนในบริการ', 'ไม่มีข้อตกลงที่สามารถวัดผลได้', 'ระบุ SLA ชัดเจน เช่น เวลาตอบสนอง, เวลากู้คืน, Uptime | สร้าง SLA Template มาตรฐานที่วัดผลได้และ Audit ได้'),
    ('10.4', 10, 76, 'ไม่มีเงื่อนไขของสัญญากับผู้ให้บริการภายนอก', 'ไม่มีเงื่อนไขในการควบคุม/ยุติสัญญาเมื่อเกิดเหตุผิดปกติ', 'สัญญาไม่กำหนดบทลงโทษหาก Supplier ไม่ปฏิบัติตาม', 'เพิ่ม Security & Termination Clause ในสัญญาทุกฉบับ | กำหนดสิทธิ์การยึดคืนข้อมูลและทรัพย์สิน'),
    ('10.5', 10, 77, 'ไม่มีการจำกัดสิทธิ์การเข้าถึงข้อมูลหรือระบบ', 'Supplier เข้าถึงข้อมูล/ระบบมากกว่าที่จำเป็น', 'ไม่มีระบบควบคุมสิทธิ์ของผู้ให้บริการ', 'ใช้หลัก Least Privilegeกับผู้ใช้งานภายนอก | สร้างบัญชีแยกเฉพาะ Supplier พร้อมกำหนดสิทธิ์ขั้นต่ำ'),
    ('10.6', 10, 78, 'ไม่มีการรับรองผู้ให้บริการตามมาตรฐานสากลหรือมีใบรับรองต่างๆ', 'เลือก Supplier ที่ไม่มีมาตรฐานหรือไม่มีใบรับรอง', 'ไม่ตรวจสอบใบรับรอง หากหมดอายุ หรือไม่อัปเดตสถานะ', 'พิจารณา Supplier ที่ได้รับ ISO 27001, ISO 27701, ISO 27018 ฯลฯ | จัดทำ Supplier Compliance Checklist'),
    ('10.7', 10, 79, 'ไม่มีการทำระบบวัดความพึงพอใจ ผู้ใช้บริการ พร้อมการติดตามการแก้ไขปัญหา', 'ผู้ใช้บริการไม่พอใจหรือไม่ได้รับการดูแลเมื่อเกิดเหตุ', 'ไม่มีระบบติดตามปัญหาและการแก้ไขจาก Supplier', 'ทำแบบสอบถามความพึงพอใจพร้อมมีระบบรับเรื่องร้องเรียน | สร้าง Customer Satisfaction Workflow พร้อมกำหนด KPI เพื่อติดตามปัญหา'),
    ('10.8', 10, 80, 'ไม่มีกระบวนการการยุติการเข้าถึงระบบเมื่อสิ้นสุดสัญญา', 'เมื่อสิ้นสุดสัญญา ยังสามารถเข้าระบบได้', 'ลืมลบบัญชีผู้ใช้งานหรือสิทธิ์หลังจบสัญญา', 'จัดทำกระบวนการ Exit Access เช่น Disable Account, ลบสิทธิ์, คืนข้อมูล | จัดทำ Exit Checklist สำหรับ Third Party Access')
ON CONFLICT (item_no) DO NOTHING;
